float AWorldSettings::FixupDeltaSeconds(float DeltaSeconds, float RealDeltaSeconds)
{
	// DeltaSeconds is assumed to be fully dilated at this time, so we will dilate the clamp range as well
	float const Dilation = GetEffectiveTimeDilation();
	float const MinFrameTime = MinUndilatedFrameTime * Dilation;
	float const MaxFrameTime = MaxUndilatedFrameTime * Dilation;

	// clamp frame time according to desired limits
	return FMath::Clamp(DeltaSeconds, MinFrameTime, MaxFrameTime);	
}

}

// Save off actual delta
float RealDeltaSeconds = DeltaSeconds;

// apply time multipliers
DeltaSeconds *= Info->GetEffectiveTimeDilation();

// Handle clamping of time to an acceptable value
const float GameDeltaSeconds = Info->FixupDeltaSeconds(DeltaSeconds, RealDeltaSeconds);
check(GameDeltaSeconds >= 0.0f);

DeltaSeconds = GameDeltaSeconds;
DeltaTimeSeconds = DeltaSeconds;
DeltaRealTimeSeconds = RealDeltaSeconds;

fn advance_with_raw_delta(&mut self, raw_delta: Duration) {
    let max_delta = self.context().max_delta;
    let clamped_delta = if raw_delta > max_delta {
        debug!(
            "delta time larger than maximum delta, clamping delta to {:?} and skipping {:?}",
            max_delta,
            raw_delta - max_delta
        );
        max_delta
    } else {
        raw_delta
    };
    let effective_speed = if self.context().paused {
        0.0
    } else {
        self.context().relative_speed
    };
    let delta = if effective_speed != 1.0 {
        clamped_delta.mul_f64(effective_speed)
    } else {
        // avoid rounding when at normal speed
        clamped_delta
    };
    self.context_mut().effective_speed = effective_speed;
    self.advance_by(delta);
}

pub fn update_virtual_time(current: &mut Time, virt: &mut Time<Virtual>, real: &Time<Real>) {
    let raw_delta = real.delta();
    virt.advance_with_raw_delta(raw_delta);
    *current = virt.as_generic();
}

fn advance_with_raw_delta(&mut self, raw_delta: Duration) {
    let max_delta = self.context().max_delta;
    let speed = if self.context().paused {
        0.0
    } else {
        self.context().relative_speed
    };
    let scaled = if speed != 1.0 {
        raw_delta.mul_f64(speed)
    } else {
        // avoid rounding when at normal speed
        raw_delta
    };
    let (effective_speed, delta) = if scaled > max_delta {
        debug!(
            "delta time larger than maximum delta, clamping delta to {:?} and skipping {:?}",
            max_delta,
            scaled - max_delta
        );
        (max_delta.as_secs_f64() / raw_delta.as_secs_f64(), max_delta)
    } else {
        (speed, scaled)
    };
    self.context_mut().effective_speed = effective_speed;
    self.advance_by(delta);
}

pub fn update_virtual_time(current: &mut Time, virt: &mut Time<Virtual>, real: &Time<Real>) {
    let raw_delta = real.delta();
    virt.advance_with_raw_delta(raw_delta);
    *current = virt.as_generic();
}
